import {armTo} from './arm-pose.js';
export const SERVICE_CONTACT=1.05,SERVICE_RELEASE=.32,SERVICE_END=1.48;
const clamp=x=>Math.max(0,Math.min(1,x)),lerp=(a,b,t)=>a.map((v,i)=>v+(b[i]-v)*t);
export function serviceMotion(age,contact,overhead){const wind=clamp(age/.75),forward=clamp((age-.75)/(SERVICE_CONTACT-.75)),follow=clamp((age-SERVICE_CONTACT)/.43),release=[.2,1.25,.32],settle=clamp((age-1.25)/.23);
 const leftWrist=age<SERVICE_RELEASE?lerp([.28,.96,.22],release,age/SERVICE_RELEASE):age<.65?lerp(release,[.25,1.80,.25],(age-SERVICE_RELEASE)/.33):lerp([.25,1.80,.25],[.38,1.12,.15],clamp((age-.65)/.65));
 const contactShaft=overhead?[0,1,0]:[-.6,.25,Math.sqrt(.5775)],backShaft=overhead?[.15,-.5,-Math.sqrt(.7275)]:[-.8,.05,-Math.sqrt(.3575)],rawShaft=forward?lerp(backShaft,contactShaft,forward):lerp([0,.92,.392],backShaft,wind),turned=follow?lerp(rawShaft,[-.75,.15,.6442],follow):rawShaft,settledShaft=lerp(turned,[.035/.4387,.43/.4387,.08/.4387],settle),norm=Math.hypot(...settledShaft),shaft=settledShaft.map(v=>v/norm),at=contact.map((v,i)=>v-contactShaft[i]*.45),back=overhead?[-.37,1.51,-.28]:[-.44,1.10,-.36],rest=[-.035,.89,.38],wrist=forward?lerp(back,at,forward):lerp(rest,back,wind);const desired=follow?lerp(wrist,[-.37,1.3,.45],follow):wrist,arm=armTo([-.22,1.34,0],lerp(desired,rest,settle),lerp([-.6,.25,-.7],[-.6,-.2,0],settle));
 return {left:armTo([.235,1.28,0],lerp(leftWrist,[.045,.91,.38],settle),lerp([.6,.15,.1],[.6,-.2,.1],settle)),right:arm,shaft,bodyYaw:Math.sin(Math.PI*follow)*.25,bodyLean:Math.sin(Math.PI*follow)*.04,contact:age>=SERVICE_CONTACT,head:arm.wrist.map((v,i)=>v+shaft[i]*.45),release};}
export function tossedBall(age,contact,heightScale=1){const r=serviceMotion(age,contact,false).release;if(age<SERVICE_RELEASE)return serviceMotion(age,contact,false).left.wrist;const t=Math.min(SERVICE_CONTACT-SERVICE_RELEASE,Math.max(0,age-SERVICE_RELEASE)),T=SERVICE_CONTACT-SERVICE_RELEASE,g=9.81/heightScale,vy=(contact[1]-r[1]+.5*g*T*T)/T;return [r[0]+(contact[0]-r[0])*t/T,r[1]+vy*t-.5*g*t*t,r[2]+(contact[2]-r[2])*t/T];}
